<script setup lang="ts">
import { computed } from 'vue'
import { useRoute } from 'vue-router'
import RulePageLayout from '../components/RulePageLayout.vue'
import CoreActionCard from '../components/CoreActionCard.vue'
import { coreActions } from '../data/coreAbilities'
import { findRulePage, rulePageNavigation } from '../data/ruleCatalog'
import { ruleSourceDocuments, type RuleSourceBlock, type RuleSourceSection } from '../data/rulesCurrent'
import diceStrip from '../assets/rules/brambleheart-dice-strip.webp'
import { useSettings } from '../state/settings'
import { formatMeasurementText } from '../rules/measurements'

const route=useRoute()
const {measurement}=useSettings()
const slug=computed(()=>String(route.params.slug||'core-rules'))
const mode=computed(()=>slug.value==='introduction'?'introduction':slug.value==='attributes-skills'?'attributes':slug.value==='abilities'?'abilities':'core')
const title=computed(()=>mode.value==='introduction'?'Introduction':mode.value==='attributes'?'Attributes & Skills':mode.value==='abilities'?'Core Actions':'Core Rules')
const pageDefinition=computed(()=>findRulePage(slug.value))
const pageSummary=computed(()=>pageDefinition.value?.summary||'')
const pageNavigation=computed(()=>rulePageNavigation(slug.value))
const sourceSections=computed(()=>mode.value==='introduction'?(ruleSourceDocuments.introduction?.sections||[]):(ruleSourceDocuments.fundamentals?.sections||[]))
const ATTRIBUTE_HEADINGS=new Set(['ATTRIBUTES','RANKS & MODIFIERS','SKILLS','SKILL TREES','EXPANDED & RESTRICTED'])

function displayText(text:string){return formatMeasurementText(text,measurement.value)}
function sectionByHeading(sections:RuleSourceSection[],heading:string){return sections.find(section=>section.heading.toUpperCase()===heading)}
function isSecondaryStatsParagraph(block:RuleSourceBlock){return block.type==='paragraph'&&/^SECONDARY STATS:/i.test(block.text.trim())}
function splitTargets(section:RuleSourceSection){
  const regular:RuleSourceBlock[]=[],targets:RuleSourceBlock[]=[]
  let targetMode=false
  for(const block of section.blocks){
    if(block.type==='paragraph'&&/ACTIVE\s*&\s*PASSIVE TARGETS/i.test(block.text)){
      targetMode=true
      const text=block.text.replace(/^ACTIVE\s*&\s*PASSIVE TARGETS\s*/i,'').trim()
      if(text)targets.push({...block,text})
      continue
    }
    ;(targetMode?targets:regular).push(block)
  }
  return{regular,targets}
}
const bodySections=computed<RuleSourceSection[]>(()=>{
  const sections=sourceSections.value.filter(section=>section.heading.toLowerCase()!=='overview')
  if(mode.value==='abilities')return[]
  if(mode.value==='introduction')return sections
  if(mode.value==='attributes'){
    const attributes=sectionByHeading(sections,'ATTRIBUTES')
    const ranks=sectionByHeading(sections,'RANKS & MODIFIERS')
    const skills=sectionByHeading(sections,'SKILLS')
    const trees=sectionByHeading(sections,'SKILL TREES')
    const expanded=sectionByHeading(sections,'EXPANDED & RESTRICTED')
    const out:RuleSourceSection[]=[]
    if(attributes)out.push({...attributes,blocks:attributes.blocks.filter(block=>!isSecondaryStatsParagraph(block))})
    if(ranks)out.push({...ranks,blocks:ranks.blocks.filter(block=>block.type==='paragraph')})
    const treeTables=(expanded?.blocks||[]).filter(block=>block.type==='table')
    if(skills||trees||treeTables.length)out.push({heading:'SKILLS',blocks:[...(skills?.blocks||[]),...(trees?.blocks||[]),...treeTables]})
    if(expanded)out.push({heading:'EXPANDED & RESTRICTED',blocks:expanded.blocks.filter(block=>block.type!=='table')})
    return out
  }
  const out:RuleSourceSection[]=[]
  for(const section of sections){
    if(ATTRIBUTE_HEADINGS.has(section.heading.toUpperCase()))continue
    if(section.heading.toUpperCase()==='EDGED & WEIGHTED ROLLS'){
      const split=splitTargets(section)
      out.push({...section,blocks:split.regular})
      if(split.targets.length)out.push({heading:'ACTIVE & PASSIVE TARGETS',blocks:split.targets})
    }else out.push(section)
  }
  return out
})

function sectionId(value:string,index:number){return`rules-${index}-${value.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'section'}`}
const targetExamples:Record<string,string>={Easy:'Routine task under light pressure',Medium:'Standard challenge with meaningful risk',Difficult:'Demanding task requiring strong skill',Hard:'Severe challenge under poor conditions','Very Hard':'Extreme feat with little margin'}
function tableRows(section:RuleSourceSection,block:RuleSourceBlock){
  if(block.type!=='table')return[]
  if(section.heading!=='ACTIVE & PASSIVE TARGETS')return block.rows
  return block.rows.map((row,index)=>index===0?[...row,'Example']:[...row,targetExamples[row[0]||'']||''])
}
function displayParagraph(_section:RuleSourceSection,text:string){return displayText(text)}
function displayHeading(value:string){const upper=value.toUpperCase();if(upper==='FORTUNE & MISFORTUNE RESULTS')return'FORTUNE & MISFORTUNE';if(upper==='CORE PRINCIPLES OF PLAY')return'PRINCIPLES OF PLAY';return value}
function isIntroductionDialogue(block:RuleSourceBlock){return mode.value==='introduction'&&block.type==='table'&&block.rows.length===1&&block.rows[0].length===1&&/^Watcher:/i.test(block.rows[0][0].trim())}
function introductionDialogueParts(block:RuleSourceBlock){if(!isIntroductionDialogue(block)||block.type!=='table')return[];const text=displayText(block.rows[0][0]);const parts:Array<{actor:string;text:string}>=[];const rx=/(Watcher|Player):\s*[“"]?([^”"]+)[”"]?/g;let match:RegExpExecArray|null;while((match=rx.exec(text)))parts.push({actor:match[1],text:match[2].trim()});return parts}
function isWelcomeLine(section:RuleSourceSection,block:RuleSourceBlock){return mode.value==='introduction'&&section.heading==='BRAMBLEHEART'&&block.type==='paragraph'&&block.text.trim()==='Welcome to Brambleheart'}
function whatYouNeedItems(section:RuleSourceSection){return mode.value==='introduction'&&section.heading==='WHAT YOU’LL NEED'?section.blocks.filter((block,index)=>block.type==='paragraph'&&index>=1&&index<=4).map(block=>block.type==='paragraph'?displayText(block.text):''):[]}
function skipWhatYouNeedParagraph(section:RuleSourceSection,index:number){return mode.value==='introduction'&&section.heading==='WHAT YOU’LL NEED'&&index>=1&&index<=4}
function isPrinciplesSection(section:RuleSourceSection){return mode.value==='introduction'&&section.heading.toUpperCase()==='CORE PRINCIPLES OF PLAY'}
function principleParts(text:string){const value=displayText(text);const index=value.indexOf(':');return index>0?{title:value.slice(0,index),body:value.slice(index+1).trim()}:{title:'',body:value}}
function sectionParagraphs(section:RuleSourceSection){return section.blocks.filter((block):block is Extract<RuleSourceBlock,{type:'paragraph'}>=>block.type==='paragraph').map(block=>displayText(block.text))}
function labeledStep(text:string){const value=displayText(text);const index=value.indexOf(':');return index>0?{title:value.slice(0,index),body:value.slice(index+1).trim()}:{title:'',body:value}}
function isGameFlowSection(section:RuleSourceSection){return mode.value==='introduction'&&section.heading==='HOW THE GAME FLOWS'}
function isFirstStepSection(section:RuleSourceSection){return mode.value==='introduction'&&section.heading==='YOUR FIRST STEP'}
function isExpandedRestrictedSection(section:RuleSourceSection){return mode.value==='attributes'&&section.heading==='EXPANDED & RESTRICTED'}
function isFormulaParagraph(section:RuleSourceSection,block:RuleSourceBlock){return section.heading==='THE RHYTHM ENGINE'&&block.type==='paragraph'&&/\(3d10\)\s*\+\s*stat/i.test(block.text)}
function isHalfStepFormula(block:RuleSourceBlock){return block.type==='paragraph'&&/^\(1d10\/2\)$/i.test(block.text.trim())}
function showConditionsGraphic(section:RuleSourceSection,blockIndex:number){return section.heading==='CONDITIONS'&&blockIndex===0}
function showFortuneGraphic(section:RuleSourceSection){return section.heading==='FORTUNE & MISFORTUNE RESULTS'}
function showHalfStepExample(section:RuleSourceSection){return section.heading==='HALF-STEP ROLLS'}
function showEdgedWeightedGraphic(section:RuleSourceSection){return section.heading==='EDGED & WEIGHTED ROLLS'}
function isTargetSection(section:RuleSourceSection){return section.heading==='ACTIVE & PASSIVE TARGETS'}
function showSecondaryStatsGraphic(section:RuleSourceSection){return mode.value==='attributes'&&section.heading==='ATTRIBUTES'}
function skillTreeName(block:RuleSourceBlock){if(block.type!=='table'||block.rows.length<2)return'';const row=block.rows[1];return row.length===1&&/Skill Tree$/i.test(row[0])?displayText(row[0]):''}
function displaySkillTreeName(name:string){return name.replace(/\s+Skill Tree$/i,' - Skill Tree')}
function skillTreeTone(name:string){return name.toLowerCase().split(' ')[0]||'skill'}
function skillTreeRows(block:RuleSourceBlock){return block.type==='table'?block.rows.slice(2).filter(row=>row.some(cell=>String(cell).trim())):[]}
const rankModifierExamples=[
  {attribute:'Agility',rank:3,modifier:'+6'},
  {attribute:'Might',rank:1,modifier:'+2'},
  {attribute:'Hide',rank:5,modifier:'+10'},
  {attribute:'Lore',rank:2,modifier:'+4'},
  {attribute:'Bravery',rank:4,modifier:'+8'},
]
const secondaryBreakdown=[
  {name:'Agility',short:'AGI',rank:'Accuracy',modifier:'Aim',extra:'Speed = 2 + AGI modifier'},
  {name:'Might',short:'MIG',rank:'Fury',modifier:'Brawl',extra:''},
  {name:'Hide',short:'HID',rank:'Guts',modifier:'Ward',extra:''},
  {name:'Lore',short:'LOR',rank:'Power',modifier:'Control',extra:''},
  {name:'Bravery',short:'BRY',rank:'Heart',modifier:'Spirit',extra:''},
]
const backPage=computed(()=>mode.value==='core'?{label:'Introduction',path:'/rules/read/introduction'}:mode.value==='attributes'?{label:'Core Rules',path:'/rules/read/core-rules'}:mode.value==='abilities'?{label:'Attributes & Skills',path:'/rules/read/attributes-skills'}:null)
const backTarget=computed(()=>backPage.value?.path||'/rules')
const backLabel=computed(()=>backPage.value?`Back to ${backPage.value.label}`:'Back to Rules')
</script>

<template>
  <RulePageLayout
    :title="title"
    section="Fundamentals"
    :summary="pageSummary"
    :parent="{label:'Fundamentals',path:'/rules/read/fundamentals-overview'}"
    :back-to="backTarget"
    :back-label="backLabel"
    prefer-back-to
    :navigation="pageNavigation"
  >
        <section v-if="mode==='abilities'" class="abilities-rule-stack">
          <article id="abilities-what" class="rule-page-section"><h2>CORE ACTIONS &amp; ABILITIES</h2><p>Core Actions are the shared actions every character can take during an encounter. They establish what a character is doing and are the only starting points for an Ability Chain. A Core Action spends the matching Instinct, Move, Combat, or Reaction opportunity and resolves according to its own Trigger, Effect, and Restrictions.</p><div class="ability-economy-graphic core-action-economy"><div class="economy-node type-instinct"><small>ROUND TIMING</small><strong>CORE ACTION · INSTINCT</strong><span class="ability-cost-pill type-instinct">INSTINCT</span></div><div class="economy-node type-move"><small>DYNAMIC</small><strong>CORE ACTION · MOVE</strong><span class="ability-cost-pill type-move">MOVE</span></div><div class="economy-node type-combat"><small>ON A TURN</small><strong>CORE ACTION · COMBAT</strong><span class="ability-cost-pill type-combat">COMBAT</span></div><div class="economy-node type-reactive"><small>WHEN TRIGGERED</small><strong>CORE ACTION · REACTION</strong><span class="ability-cost-pill type-reactive">REACTION</span></div></div><p>Each character has one Core Instinct, one Core Move, one Core Combat, and one Core Reaction opportunity per round. Move Actions are dynamic and may be used whenever their own Trigger permits. A Core Combat Action is normally used on a turn. The Reaction Core Action is spent when that character resolves an eligible Reactive Ability.</p></article>
          <article id="abilities-how" class="rule-page-section"><h2>ABILITIES</h2><p>Abilities are rules a character gains from Traits, Talents, Spells, equipment, and other sources. An Ability can modify a Core Action, be resolved through a Core Action, or trigger from an event created during the same Ability Chain. Abilities do not begin their own chains; they build from the Core Action that started the chain, and each specific character’s copy of an Ability can resolve only once in that chain.</p><p>Unless otherwise stated, effects from the same named ability or spell do not stack. If a character would be affected by multiple instances of the same ability or spell at the same time, apply only one instance.</p><div class="ordered-flow"><div class="mini-rule-node core"><strong>Choose a Core Action</strong><small>Spend the matching Core Action opportunity.</small><span class="ability-cost-pill type-core">CORE</span></div><span class="flow-arrow" aria-hidden="true">→</span><div class="mini-rule-node modifier"><strong>Resolve Abilities</strong><small>Talent · Spell · Trait · Equipment</small><span class="ability-cost-pill type-reactive">ABILITY</span></div><span class="flow-arrow" aria-hidden="true">→</span><div class="mini-rule-node result"><strong>Finish the chain</strong><small>Stop when no unused Ability has a legal trigger.</small><span class="ability-cost-pill type-passive">END</span></div></div></article>
          <article id="abilities-example" class="rule-page-section"><h2>ACTION &amp; ABILITY EXAMPLE</h2><p>One Core Combat Action can lead into several Abilities without creating another Core Combat opportunity.</p><div class="ordered-flow"><div class="mini-rule-node magic"><strong>Arcane Command</strong><small>Selu spends the Core Combat Action and casts Ballad of the Courageous.</small><div class="keyword-pill-row"><span class="ability-cost-pill type-core">CORE</span><span class="ability-cost-pill type-combat">COMBAT</span><span class="ability-cost-pill type-magic">MAGIC</span></div></div><span class="flow-arrow" aria-hidden="true">→</span><div class="mini-rule-node spell"><strong>Ballad resolves</strong><small>The Spell is an Ability resolved through Arcane Command and grants its listed Enhance.</small><div class="keyword-pill-row"><span class="ability-cost-pill type-ability">ABILITY</span><span class="ability-cost-pill type-magic">MAGIC</span></div></div><span class="flow-arrow" aria-hidden="true">→</span><div class="mini-rule-node talent"><strong>Hearth Touch</strong><small>Because an Enhance was granted, Hearth Touch resolves from its trigger if it has not already resolved in this chain.</small><div class="keyword-pill-row"><span class="ability-cost-pill type-ability">ABILITY</span><span class="ability-cost-pill type-passive">PASSIVE</span><span class="ability-cost-pill type-magic">MAGIC</span></div></div></div></article>
          <article id="abilities-reactive" class="rule-page-section"><h2>REACTION EXAMPLE</h2><p>Brann uses Hero’s Charge and its movement satisfies Nessa’s Pack Tactics Trigger. Nessa may spend her Reaction Core Action to resolve Pack Tactics, then the original Ability Chain continues.</p><div class="ordered-flow"><div class="mini-rule-node core"><strong>Hero’s Charge</strong><small>Brann spends a Core Move Action and moves as part of the charge.</small><span class="ability-cost-pill type-move">CORE</span></div><span class="flow-arrow" aria-hidden="true">→</span><div class="mini-rule-node reactive"><strong>Reaction</strong><small>Pack Tactics is now eligible, so Nessa spends her Reaction Core Action.</small><span class="ability-cost-pill type-reactive">REACTION</span></div><span class="flow-arrow" aria-hidden="true">→</span><div class="mini-rule-node ally"><strong>Pack Tactics</strong><small>Nessa resolves the Reactive Ability once, then the same Ability Chain continues.</small><div class="keyword-pill-row"><span class="ability-cost-pill type-ability">ABILITY</span><span class="ability-cost-pill type-reactive">REACTIVE</span></div></div></div></article>
          <article id="abilities-chaining" class="rule-page-section"><h2>CHAINING ABILITIES</h2><p>An Ability Chain begins with a Core Action and continues while its results create legal Ability triggers. Reactions from the acting character, allies, and enemies can join the same chain through each character’s own Reaction Core Action.</p><div class="chaining-grid"><div class="chaining-step"><span class="chaining-step-number">1</span><div class="mini-rule-node core"><strong>Hero’s Charge</strong><small>Brann begins with the Hero’s Charge Core Action.</small><div class="keyword-pill-row"><span class="ability-cost-pill type-core">CORE</span><span class="ability-cost-pill type-move">MOVE</span></div></div></div><div class="chaining-step"><span class="chaining-step-number">2</span><div class="mini-rule-node modifier"><strong>Heroic Surge</strong><small>A compatible Charge Ability builds from the Core Action.</small><div class="keyword-pill-row"><span class="ability-cost-pill type-ability">ABILITY</span><span class="ability-cost-pill type-move">MOVE</span></div></div></div><div class="chaining-step"><span class="chaining-step-number">3</span><div class="mini-rule-node reactive"><strong>Reaction</strong><small>Nessa’s Pack Tactics Trigger becomes legal, so Nessa spends her Reaction Core Action.</small><span class="ability-cost-pill type-reactive">CORE</span></div></div><div class="chaining-step"><span class="chaining-step-number">4</span><div class="mini-rule-node ally"><strong>Pack Tactics</strong><small>Nessa resolves Pack Tactics once in this chain and shifts into position.</small><div class="keyword-pill-row"><span class="ability-cost-pill type-ability">ABILITY</span><span class="ability-cost-pill type-reactive">REACTIVE</span></div></div></div><div class="chaining-step"><span class="chaining-step-number">5</span><div class="mini-rule-node reactive"><strong>Reaction</strong><small>The Blight Warrior has Stillroot available and spends its Reaction Core Action.</small><span class="ability-cost-pill type-reactive">CORE</span></div></div><div class="chaining-step"><span class="chaining-step-number">6</span><div class="mini-rule-node enemy"><strong>Stillroot</strong><small>The Blight Warrior resolves Stillroot once for this Ability Chain.</small><div class="keyword-pill-row"><span class="ability-cost-pill type-ability">ABILITY</span><span class="ability-cost-pill type-reactive">REACTIVE</span></div></div></div><div class="chaining-step"><span class="chaining-step-number">7</span><div class="mini-rule-node reactive"><strong>Reaction</strong><small>Ilyra has Pouncer available and spends her Reaction Core Action.</small><span class="ability-cost-pill type-reactive">CORE</span></div></div><div class="chaining-step"><span class="chaining-step-number">8</span><div class="mini-rule-node ally"><strong>Pouncer</strong><small>Ilyra resolves Pouncer once if its Ward-failure Trigger is satisfied.</small><div class="keyword-pill-row"><span class="ability-cost-pill type-ability">ABILITY</span><span class="ability-cost-pill type-reactive">REACTIVE</span></div></div></div><div class="chaining-step"><span class="chaining-step-number">9</span><div class="mini-rule-node result"><strong>Chain ends</strong><small>When no unresolved Ability instance has a legal Trigger, the Ability Chain ends.</small><span class="ability-cost-pill type-passive">END</span></div></div></div><div class="chain-resolution-note card-surface"><strong>Once per Ability Chain:</strong><span>A specific character’s copy of an Ability can resolve only once during the same Ability Chain. If another character possesses the same named Ability, that is a separate Ability instance and may resolve once in that chain as well.</span></div></article>
          <article id="abilities-core" class="rule-page-section"><h2>CORE ACTIONS</h2><p>These are the shared Core Actions that begin Ability Chains or provide universal encounter responses.</p><details class="core-action-catalog" open><summary>Complete Core Action List <span>{{ coreActions.length }} actions</span></summary><div class="core-action-grid"><CoreActionCard v-for="action in coreActions" :key="action.name" :action="action" /></div></details></article>
        </section>

        <article v-for="(section,index) in bodySections" v-else :id="sectionId(section.heading,index)" :key="`${section.heading}-${index}`" class="rule-page-section">
          <h2>{{ displayHeading(section.heading) }}</h2>
          <figure v-if="mode==='core'&&section.heading==='THE RHYTHM ENGINE'" class="fundamentals-rule-dice"><img :src="diceStrip" alt="Illustrated polyhedral dice" /></figure>
          <template v-if="showSecondaryStatsGraphic(section)"><p class="secondary-stats-summary">Secondary stats are derived values tied to an Attribute. A secondary stat uses either that Attribute’s Rank or its modifier; its rule tells you which value applies.</p><div class="attribute-breakdown-graphic"><article v-for="item in secondaryBreakdown" :key="item.short" class="attribute-breakdown-card"><header><strong>{{ item.name }}</strong><small>{{ item.short }}</small></header><div><span>Rank</span><b>→</b><strong>{{ item.rank }}</strong></div><div><span>Modifier</span><b>→</b><strong>{{ item.modifier }}</strong></div><small v-if="item.extra">{{ item.extra }}</small></article></div></template>
          <div v-if="mode==='attributes'&&section.heading==='RANKS & MODIFIERS'" class="rank-modifier-graphic" role="img" aria-label="Examples showing each Attribute with a Rank from one through five and its corresponding modifier."><article v-for="item in rankModifierExamples" :key="item.attribute"><strong>{{ item.attribute }}</strong><span><small>Rank</small><b>{{ item.rank }}</b></span><i>→</i><span><small>Modifier</small><b>{{ item.modifier }}</b></span></article></div>
          <ul v-if="isPrinciplesSection(section)" class="principles-list"><li v-for="(block,principleIndex) in section.blocks" :key="principleIndex"><template v-if="block.type==='paragraph'"><strong v-if="principleParts(block.text).title">{{ principleParts(block.text).title }}:</strong><span>{{ principleParts(block.text).body }}</span></template></li></ul>
          <template v-else-if="isGameFlowSection(section)"><p>{{ sectionParagraphs(section)[0] }}</p><div class="intro-step-grid game-flow-grid"><article v-for="line in sectionParagraphs(section).slice(1,5)" :key="line"><strong>{{ labeledStep(line).title }}</strong><span>{{ labeledStep(line).body }}</span></article></div><p>{{ sectionParagraphs(section)[5] }}</p></template>
          <template v-else-if="isFirstStepSection(section)"><p>{{ sectionParagraphs(section)[0] }}</p><p>{{ sectionParagraphs(section)[1] }}</p><p>{{ sectionParagraphs(section)[2] }}</p><div class="intro-step-grid first-step-grid"><article v-for="line in sectionParagraphs(section).slice(3,6)" :key="line"><strong>{{ labeledStep(line).title }}</strong><span>{{ labeledStep(line).body }}</span></article></div><p class="first-step-closing"><strong>{{ sectionParagraphs(section)[6] }}</strong></p><p>{{ sectionParagraphs(section)[7] }}</p></template>
          <template v-else-if="isExpandedRestrictedSection(section)"><p>{{ sectionParagraphs(section)[0] }}</p><div class="expanded-restricted-grid"><section v-for="kind in ['EXPANDED','RESTRICTED']" :key="kind" class="expanded-restricted-column"><article class="expanded-restricted-definition"><strong>{{ kind }}</strong><span>{{ labeledStep(sectionParagraphs(section).find(line=>labeledStep(line).title===kind)||'').body }}</span></article><article class="expanded-restricted-example"><small>EXAMPLE</small><span>{{ labeledStep(sectionParagraphs(section).find(line=>labeledStep(line).title===`${kind} EXAMPLE`)||'').body }}</span></article></section></div></template>
          <template v-else-if="whatYouNeedItems(section).length"><p v-if="section.blocks[0]?.type==='paragraph'">{{ displayText(section.blocks[0].text) }}</p><ul class="what-you-need-list"><li v-for="item in whatYouNeedItems(section)" :key="item">{{ item }}</li></ul><p v-if="section.blocks[5]?.type==='paragraph'">{{ displayText(section.blocks[5].text) }}</p></template>
          <template v-else v-for="(block,blockIndex) in section.blocks" :key="blockIndex">
            <div v-if="isFormulaParagraph(section,block)" class="core-roll-formula">3d10 + Stat + Conditions</div>
            <div v-else-if="block.type==='paragraph'&&isWelcomeLine(section,block)" class="brambleheart-welcome-graphic"><small>WELCOME</small><strong>{{ displayParagraph(section,block.text) }}</strong></div>
            <template v-else-if="skipWhatYouNeedParagraph(section,blockIndex)"></template>
            <p v-else-if="block.type==='paragraph'&&!isHalfStepFormula(block)">{{ displayParagraph(section,block.text) }}</p>
            <div v-else-if="block.type==='paragraph'" class="half-step-rule-graphic"><div class="half-step-roll-node"><small>Roll one die</small><strong>d10</strong></div><span class="half-step-arrow">↓</span><div class="half-step-band-grid"><div class="half-step-band-node"><small>Natural result</small><strong>1–5</strong><b>→ 1</b></div><div class="half-step-band-node"><small>Natural result</small><strong>6–10</strong><b>→ 2</b></div></div><small class="half-step-read-note">Read the natural die result by band. Do not divide the number shown on the die.</small></div>
            <article v-else-if="skillTreeName(block)" class="skill-tree-card" :class="`skill-tree-${skillTreeTone(skillTreeName(block))}`"><header><strong>{{ displaySkillTreeName(skillTreeName(block)) }}</strong><div class="skill-tree-column-headings"><small>Skill</small><small>Description</small><small>Example</small></div></header><div class="skill-tree-list"><div v-for="(row,rowIndex) in skillTreeRows(block)" :key="rowIndex"><strong>{{ displayText(row[0]||'') }}</strong><span>{{ displayText(row[1]||'') }}</span><small>{{ displayText(row[2]||'') }}</small></div></div></article>
            <div v-else-if="isIntroductionDialogue(block)" class="intro-dialogue-example"><p v-for="part in introductionDialogueParts(block)" :key="`${part.actor}-${part.text}`"><strong>{{ part.actor }}:</strong> <span>“{{ part.text }}”</span></p></div><div v-else class="fundamentals-table-wrap" :class="{'target-example-table':isTargetSection(section)}"><table><tbody><tr v-for="(row,rowIndex) in tableRows(section,block)" :key="rowIndex"><td v-for="(cell,cellIndex) in row" :key="cellIndex">{{ displayText(cell) }}</td></tr></tbody></table></div>
